16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "birth_date")
58	    private LocalDate birthDate;
59	
60	    @Column(name = "customer_code")
61	    private String customerCode;
62	
63	    @Column(name = "household_id")
64	    private String householdId;
65	
66	    @Column(name = "namesake_count")
67	    private Integer namesakeCount;
68	
69	    @Column(name = "bulk_signup_warning")
70	    private Boolean bulkSignupWarning;
71	
72	    @Column(name = "household_size")
73	    private Integer householdSize;
74	
75	    @Column(name = "postcode")
76	    private String postcode;
77	
78	    @Column(name = "possible_duplicate")
79	    private Boolean possibleDuplicate;
80	
81	    @Column(name = "possible_duplicate_of")
82	    private Integer possibleDuplicateOf;
83	
84	    @Transient
85	    private boolean declaredHouseholdMember;
86	
87	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
88	    private Set<Pet> pets;
89	
90	    public String getAddress() {
91	        return this.address;
92	    }
93	
94	    public void setAddress(String address) {
95	        this.address = address;
96	    }
97	
98	    public String getCity() {
99	        return this.city;
100	    }
101	
102	    public void setCity(String city) {
103	        this.city = city;
104	    }
105	
106	    public String getTelephone() {
107	        return this.telephone;
108	    }
109	
110	    public void setTelephone(String telephone) {
111	        this.telephone = telephone;
112	    }
113	
114	    public String getEmail() {
115	        return this.email;
116	    }
117	
118	    public void setEmail(String email) {
119	        this.email = email;
120	    }
121	
122	    public LocalDate getRegistrationDate() {
123	        return this.registrationDate;
124	    }
125	
126	    public void setRegistrationDate(LocalDate registrationDate) {
127	        this.registrationDate = registrationDate;
128	    }
129	
130	    public LocalDate getBirthDate() {
131	        return this.birthDate;
132	    }
133	
134	    public void setBirthDate(LocalDate birthDate) {
135	        this.birthDate = birthDate;
136	    }
137	
138	    public String getCustomerCode() {
139	        return this.customerCode;
140	    }
141	
142	    public void setCustomerCode(String customerCode) {
143	        this.customerCode = customerCode;
144	    }
145	
146	    public String getHouseholdId() {
147	        return this.householdId;
148	    }
149	
150	    public void setHouseholdId(String householdId) {
151	        this.householdId = householdId;
152	    }
153	
154	    public Integer getNamesakeCount() {
155	        return this.namesakeCount;
156	    }
157	
158	    public void setNamesakeCount(Integer namesakeCount) {
159	        this.namesakeCount = namesakeCount;
160	    }
161	
162	    public Boolean getBulkSignupWarning() {
163	        return this.bulkSignupWarning;
164	    }
165	
166	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
167	        this.bulkSignupWarning = bulkSignupWarning;
168	    }
169	
170	    public Integer getHouseholdSize() {
171	        return this.householdSize;
172	    }
173	
174	    public void setHouseholdSize(Integer householdSize) {
175	        this.householdSize = householdSize;
176	    }
177	
178	    public String getPostcode() {
179	        return this.postcode;
180	    }
181	
182	    public void setPostcode(String postcode) {
183	        this.postcode = postcode;
184	    }
185	
186	    /**
187	     * Whether this owner deliberately declared, when created, that it shares its
188	     * household with an existing owner (the request's {@code sharesHousehold} flag).
189	     * A declared member is created despite occupying an existing household and is not
190	     * treated as a suspected duplicate. This is a request-scoped flag, not persisted.
191	     */
192	    @Transient
193	    public boolean isDeclaredHouseholdMember() {
194	        return this.declaredHouseholdMember;
195	    }
196	
197	    public void setDeclaredHouseholdMember(boolean declaredHouseholdMember) {
198	        this.declaredHouseholdMember = declaredHouseholdMember;
199	    }
200	
201	    /**
202	     * Whether this owner, when created, was found to be a possible (soft) duplicate of an
203	     * existing owner: not a hard duplicate, but sharing that owner's last name and postcode
204	     * while carrying a different telephone. See {@link #getPossibleDuplicateOf()}.
205	     */
206	    public Boolean getPossibleDuplicate() {
207	        return this.possibleDuplicate;
208	    }
209	
210	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
211	        this.possibleDuplicate = possibleDuplicate;
212	    }
213	
214	    /**
215	     * The id of the existing owner this owner was flagged as a possible duplicate of, or
216	     * null when it is not a possible duplicate. See {@link #getPossibleDuplicate()}.
217	     */
218	    public Integer getPossibleDuplicateOf() {
219	        return this.possibleDuplicateOf;
220	    }
221	
222	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
223	        this.possibleDuplicateOf = possibleDuplicateOf;
224	    }
225	
226	    /**
227	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY
228	     * is the last two digits of the registration date's year (e.g. {@code "NSW-1A2B3C4D-M26"}).
229	     * Derived from the owner's own fields, so it stays consistent with them.
230	     */
231	    @Transient
232	    public String getMembershipNumber() {
233	        if (this.customerCode == null || this.registrationDate == null) {
234	            return null;
235	        }
236	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
237	    }
238	
239	    /**
240	     * The owner's customer-code check digit: the single Luhn check digit (0-9) computed
241	     * over the digits of the customer code. Derived from the owner's own customer code,
242	     * so it stays consistent with it.
243	     */
244	    @Transient
245	    public Integer getCheckDigit() {
246	        if (this.customerCode == null) {
247	            return null;
248	        }
249	        return LuhnCheckDigit.of(this.customerCode);
250	    }
251	
252	    /**
253	     * The owner's membership points, starting at zero: two points are added when an email is
254	     * on file, one more when the owner is unique (namesake count of zero), two more for a
255	     * household of three or more, and three more when the owner has accrued more than a year of
256	     * tenure (see {@link Tenure}). Derived from the owner's own fields, so it stays consistent
257	     * with them.
258	     */
259	    @Transient
260	    public Integer getMembershipPoints() {
261	        int points = 0;
262	        boolean hasEmail = this.email != null && !this.email.isEmpty();
263	        if (hasEmail) {
264	            points += 2;
265	        }
266	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
267	        if (unique) {
268	            points += 1;
269	        }
270	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
271	        if (largeHousehold) {
272	            points += 2;
273	        }
274	        boolean tenured = this.registrationDate != null
275	            && Tenure.qualifiesForTopLevel(this.registrationDate, LocalDate.now());
276	        if (tenured) {
277	            points += 3;
278	        }
279	        return points;
280	    }
281	
282	    /**
283	     * The owner's membership level, a number from 1 to 4, derived from their
284	     * {@link #getMembershipPoints() membership points} (see {@link MembershipLevel}). Derived
285	     * from the owner's own fields, so it stays consistent with them.
286	     */
287	    @Transient
288	    public Integer getMembershipLevel() {
289	        return MembershipLevel.forPoints(getMembershipPoints());
290	    }
291	
292	    /**
293	     * The owner's locality: the canonical region, taken as the region segment of the
294	     * customer code (formatted {@code '<REGION>-<HASH8>'}), so the locality stays
295	     * consistent with the owner's identity. When no customer code has been assigned yet
296	     * it falls back to resolving the region directly from the postcode and city (see
297	     * {@link RegionResolver}), the same rule the customer code itself is built from.
298	     */
299	    @Transient
300	    public String getLocality() {
301	        if (this.customerCode != null) {
302	            int separator = this.customerCode.indexOf('-');
303	            if (separator > 0) {
304	                return this.customerCode.substring(0, separator);
305	            }
306	        }
307	        return RegionResolver.regionFor(this.postcode, this.city);
308	    }
309	
310	    /**
311	     * The owner's timezone: the IANA timezone name for their {@link #getLocality() locality},
312	     * taken from the fixed region-to-timezone table (see {@link RegionTimezoneTable}), so it
313	     * stays consistent with the owner's region. Null when the locality has no known timezone.
314	     */
315	    @Transient
316	    public String getTimezone() {
317	        return RegionTimezoneTable.timezoneFor(getLocality());
318	    }
319	
320	    /**
321	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is on
322	     * file, otherwise {@code "PHONE"}. Derived from the owner's own contact details, so it
323	     * stays consistent with them.
324	     */
325	    @Transient
326	    public String getContactPreference() {
327	        boolean hasEmail = this.email != null && !this.email.isEmpty();
328	        return hasEmail ? "EMAIL" : "PHONE";
329	    }
330	
331	    /**
332	     * The owner's telephone formatted for human display: the stored E.164 number
333	     * rendered as its country calling code, a space and the national digits grouped
334	     * in threes (e.g. {@code "+61 412 345 678"}). The raw {@link #getTelephone()}
335	     * stays in E.164 form. Derived from the owner's own telephone, so it stays
336	     * consistent with it. See {@link TelephoneFormatter}.
337	     */
338	    @Transient
339	    public String getTelephoneDisplay() {
340	        return TelephoneFormatter.toDisplay(this.telephone);
341	    }
342	
343	    /**
344	     * The owner's identity key: the single derived value used to detect duplicate owners,
345	     * formed as {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
346	     * Two owners are duplicates only when their whole identity keys are equal, so members
347	     * of one household (sharing a household id) but with different telephones stay distinct.
348	     * Derived from the owner's own fields, so it stays consistent with them.
349	     */
350	    @Transient
351	    public String getIdentityKey() {
352	        String telephonePart = this.telephone == null ? "" : this.telephone;
353	        String emailPart = this.email == null ? "" : this.email;
354	        String householdPart = this.householdId == null ? "" : this.householdId;
355	        return telephonePart + "|" + emailPart + "|" + householdPart;
356	    }
357	
358	    /**
359	     * The owner's age band relative to their registration date: {@code "MINOR"} when
360	     * under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or older.
361	     * Derived from the owner's own birth and registration dates, so it stays consistent
362	     * with them; null until a birth date is on file. See {@link AgeBand}.
363	     */
364	    @Transient
365	    public String getAgeBand() {
366	        if (this.birthDate == null || this.registrationDate == null) {
367	            return null;
368	        }
369	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
370	    }
371	
372	    /**
373	     * Normalize the registration date before persisting: default it to the server's
374	     * current date when none was supplied, then roll it forward onto a business day so
375	     * every newly persisted owner is registered on a weekday.
376	     */
377	    @PrePersist
378	    void normalizeRegistrationDate() {
379	        if (this.registrationDate == null) {
380	            this.registrationDate = LocalDate.now();
381	        }
382	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
383	    }
384	
385	    protected Set<Pet> getPetsInternal() {
386	        if (this.pets == null) {
387	            this.pets = new HashSet<>();
388	        }
389	        return this.pets;
390	    }
391	
392	    protected void setPetsInternal(Set<Pet> pets) {
393	        this.pets = pets;
394	    }
395	
396	    public List<Pet> getPets() {
397	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
398	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
399	        return Collections.unmodifiableList(sortedPets);
400	    }
401	
402	    public void setPets(List<Pet> pets) {
403	        this.pets = new HashSet<>(pets);
404	    }
405	
406	    public void addPet(Pet pet) {
407	        getPetsInternal().add(pet);
408	        pet.setOwner(this);
409	    }
410	
411	    /**
412	     * Return the Pet with the given name, or null if none found for this Owner.
413	     *
414	     * @param name to test
415	     * @return true if pet name is already in use
416	     */
417	    public Pet getPet(String name) {
418	        return getPet(name, false);
419	    }
420	
421	    /**
422	     * Return the Pet with the given name, or null if none found for this Owner.
423	     *
424	     * @param name to test
425	     * @return true if pet name is already in use
426	     */
427	    public Pet getPet(String name, boolean ignoreNew) {
428	        name = name.toLowerCase();
429	        for (Pet pet : getPetsInternal()) {
430	            if (!ignoreNew || !pet.isNew()) {
431	                String compName = pet.getName();
432	                compName = compName.toLowerCase();
433	                if (compName.equals(name)) {
434	                    return pet;
435	                }
436	            }
437	        }
438	        return null;
439	    }
440	
441	    public Pet getPet(Integer petId) {
442	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
443	    }
444	
445	    @Override
446	    public String toString() {
447	        return new ToStringCreator(this)
448	
449	            .append("id", this.getId())
450	            .append("new", this.isNew())
451	            .append("lastName", this.getLastName())
452	            .append("firstName", this.getFirstName())
453	            .append("address", this.address)
454	            .append("city", this.city)
455	            .append("telephone", this.telephone)
456	            .toString();
457	    }
458	}
